//! Checked source-neutral helper controls and incomplete DATA rejection.
#[path="../fixtures/native-shadow-look/fixture.rs"]mod fixture;
use crate::{captured_raw_tree_pages::{Policy,Data},captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure};
use std::{path::Path,sync::Arc,io};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>,stop:bool}
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{if self.stop{return Ok(false)}for(relative,text)in &self.rows{if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
fn policy(kind:&str)->Policy{if kind=="dx_constructor_shadow"{Policy::ConstructorShadow}else{Policy::LookEffects}}
#[test]fn shadow_look_checked_helpers_fail_before_growth_preserve_actual_1450_and_recover(){let root=std::env::current_dir().unwrap().join("shadow-look-source-neutral");let b=Budget::new(512*1024*1024).unwrap();let mut source=String::new();for n in 0..300{source.push_str(&format!("/proc/cap_builder_{n}()\n\treturn new /datum/capability/x\nDECLARE_APPEARANCE_PROC(/obj/custom, PROC_REF(custom_{n}), list())\n/obj/custom/proc/custom_{n}()\n\tstate = {n}\n"));}crate::captured_raw_file::with_original_policy_file(&root,&root.join("code/library/capabilities/a.dm"),source.into(),0,&b,&mut|_,views|{let file=views.source_file()?;for look in [false,true]{let tiny=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=crate::captured_allow_annotations::Operation{budget:&tiny,poll:&||Ok(())};let mut temp=crate::captured_allow_annotations::Operation{budget:&b,poll:&||Ok(())};let denied=if look{crate::sys_look_effects_policy::names_in_file_using(file,&mut keep,&mut temp).map(|_|())}else{crate::sys_constructor_shadow_policy::file_facts(file,&mut keep,&mut temp).map(|_|())};assert!(matches!(denied,Err(Failure::Operational(ref e))if e.kind()==io::ErrorKind::OutOfMemory));let calls=std::cell::Cell::new(0usize);let poll=||{let n=calls.get()+1;calls.set(n);if n==32{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let mut keep=crate::captured_allow_annotations::Operation{budget:&b,poll:&poll};let failed=if look{crate::sys_look_effects_policy::names_in_file_using(file,&mut keep,&mut temp).map(|_|())}else{crate::sys_constructor_shadow_policy::file_facts(file,&mut keep,&mut temp).map(|_|())};assert!(matches!(failed,Err(Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));assert_eq!(calls.get(),32);let mut keep=crate::captured_allow_annotations::Operation{budget:&b,poll:&||Ok(())};if look{let names=crate::sys_look_effects_policy::names_in_file_using(file,&mut keep,&mut temp)?;assert_eq!(names.len(),300);let names=crate::sys_look_effects_policy::merge([&names],&mut keep)?;assert_eq!(crate::sys_look_effects_policy::judge_using(file,&names,&mut keep,&mut temp)?.len(),300);}else{assert_eq!(crate::sys_constructor_shadow_policy::file_facts(file,&mut keep,&mut temp)?.len(),600);}}Ok(true)}).unwrap();}
#[test]fn shadow_look_incomplete_data_never_becomes_complete_and_both_original_metadata_names_are_closed(){let root=std::env::current_dir().unwrap().join("shadow-look-incomplete-data");for kind in fixture::KINDS{let b=Budget::new(256*1024*1024).unwrap();let config=Config::capture(crate::captured_raw_policy::Configuration::Captured(fixture::configuration(kind,0).as_bytes())).unwrap();let rows=fixture::files(kind,0).into_iter().filter(|(relative,_)|policy(kind).selects_path(relative)).map(|(relative,text)|{let original=dm_preprocess::AcquiredSource::from_original_bytes(text.into_bytes(),());(relative.into(),original.lease().source_text().clone())}).collect();let mut pages=Pages{root:&root,rows,budget:Arc::clone(&b),stop:true};assert!(matches!(crate::captured_raw_tree_pages::collect(&pages,policy(kind),&config,&b,&||Ok(())),Err(Failure::Unsupported(message))if message.contains("EOF")));pages.stop=false;let data=crate::captured_raw_tree_pages::collect(&pages,policy(kind),&config,&b,&||Ok(())).unwrap();assert!(!data.sites().is_empty());assert_eq!(policy(kind).metadata().group,"sys");assert_eq!(policy(kind).source_visits(),2);assert!(Policy::from_name(&format!("{}_unported",fixture::name(kind))).is_none());}}
